{"command":"python3 -c "
import json, re
d=json.load(open('inputs/wikidata/wikidata_pois_sample.json'))
b=d['results']['bindings']
seen={}
for r in b:
    seen.setdefault(r['qid'],0)
    seen[r['qid']]+=1
dups={k:v for k,v in seen.items() if v>1}
print('dups:', dups)
for r in b:
    if dups.get(r['qid']) and r['qid'] in dups:
        print(r)
    if not r['itemLabel'].strip():
        print('EMPTY LABEL', r['qid'], repr(r.get('coord')), repr(r.get('poi_type')))
    c=r.get('coord')
    m=re.fullmatch(r'Point\(([-\d.]+) ([-\d.]+)\)', c)
    if not m: print('BAD COORD', c)
    else:
        lon,lat=float(m.group(1)),float(m.group(2))
        if not(-90<=lat<=90 and -180<=lon<=180): print('RANGE', lon, lat)
""}

